#!/usr/bin/env python3
import sys, json, time, urllib.request, urllib.error

URL = "http://127.0.0.1:4000/v1/chat/completions"
PROMPT = "Reply with exactly one word: OK"
TIMEOUT = 30

# Models known to not support temperature (e.g., some reasoning models)
NO_TEMP_HINTS = ("o1", "o3", "o4", "gpt-5")

def needs_no_temp(model):
    m = model.lower()
    return any(h in m for h in NO_TEMP_HINTS)

def call(model, with_temp=True):
    payload = {
        "model": model,
        "messages": [{"role": "user", "content": PROMPT}],
        "max_tokens": 20,
    }
    if with_temp:
        payload["temperature"] = 0
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        URL, data=data,
        headers={"Content-Type": "application/json", "Authorization": "Bearer sk-anything"},
        method="POST",
    )
    with urllib.request.urlopen(req, timeout=TIMEOUT) as resp:
        return json.loads(resp.read().decode("utf-8"))

def test_model(model):
    start = time.time()
    try:
        with_temp = not needs_no_temp(model)
        try:
            result = call(model, with_temp=with_temp)
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", errors="ignore")
            if with_temp and ("temperature" in body.lower() or e.code == 400):
                result = call(model, with_temp=False)
            else:
                raise
        latency = time.time() - start
        text = result["choices"][0]["message"]["content"].strip()
        return True, latency, text[:50]
    except urllib.error.HTTPError as e:
        latency = time.time() - start
        body = e.read().decode("utf-8", errors="ignore")[:50]
        return False, latency, f"HTTP {e.code}: {body}"
    except Exception as e:
        latency = time.time() - start
        return False, latency, f"ERR: {str(e)[:45]}"

def load_models(path):
    with open(path) as f:
        cfg = json.load(f)
    if isinstance(cfg, list):
        items = cfg
    else:
        items = cfg.get("model_list") or cfg.get("models") or []
    models = []
    for it in items:
        if isinstance(it, str):
            models.append(it)
        elif isinstance(it, dict):
            name = it.get("model_name") or it.get("name") or it.get("model")
            if name:
                models.append(name)
    return models

def main():
    if len(sys.argv) < 2:
        print("Usage: test_models.py <config.json>")
        sys.exit(1)

    models = load_models(sys.argv[1])
    if not models:
        print("No models found in config.")
        sys.exit(1)

    results = []
    for m in models:
        print(f"Testing {m}...", flush=True)
        ok, lat, resp = test_model(m)
        results.append((m, ok, lat, resp))

    name_w = max(len("Model"), max(len(r[0]) for r in results))
    resp_w = max(len("Response"), max(len(r[3]) for r in results))
    header = f"{'Model':<{name_w}}  {'Status':<6}  {'Latency':>8}  {'Response':<{resp_w}}"
    print()
    print(header)
    print("-" * len(header))
    for name, ok, lat, resp in results:
        status = "PASS" if ok else "FAIL"
        print(f"{name:<{name_w}}  {status:<6}  {lat:>7.2f}s  {resp:<{resp_w}}")

    passed = sum(1 for r in results if r[1])
    failed = len(results) - passed
    print(f"\nTotal: {len(results)} models | ✅ {passed} working | ❌ {failed} failed")

if __name__ == "__main__":
    main()
